package org.najwa.core

import org.junit.Assert.*
import org.junit.Test
import java.time.*
import java.time.chrono.HijrahDate
import java.time.temporal.ChronoField

class PrayerTest {
    private val calculator=PrayerCalculator()
    @Test fun allProfilesProduceOrderedSixEventsForSaudiCitiesAcrossYear() {for(city in Cities.all.take(12))for(method in Method.entries)for(month in 1..12) {val day=calculator.calculate(LocalDate.of(2026,month,15),Preferences(city=city,method=method));assertTrue("${city.name}/$method/$month",day.complete);assertEquals(5,day.events.count {it.prayer.isPrayer});assertTrue(day.events.zipWithNext().all {it.first.time<it.second.time})}}
    @Test fun hanafiAsrIsLaterAndOtherEventsUnchanged() {val date=LocalDate.of(2026,11,6);val a=calculator.calculate(date,Preferences()).events;val b=calculator.calculate(date,Preferences(hanafi=true)).events;assertTrue(b.first {it.prayer==Prayer.ASR}.time>a.first {it.prayer==Prayer.ASR}.time);assertEquals(a.filter {it.prayer!=Prayer.ASR},b.filter {it.prayer!=Prayer.ASR})}
    @Test fun sunriseIsNeverNextPrayer() {val p=Preferences();val days=calculator.around(Instant.parse("2026-11-06T02:30:00Z"),p);val events=days.flatMap {it.events};val sunrise=days[1].events.first {it.prayer==Prayer.SUNRISE};assertNotEquals(Prayer.SUNRISE,timeline(events,sunrise.time.minusSeconds(10))!!.next.prayer)}
    @Test fun yearBoundaryFindsTomorrowFajr() {val p=Preferences();val now=Instant.parse("2026-12-31T20:00:00Z");val t=timeline(calculator.around(now,p).flatMap {it.events},now)!!;assertEquals(Prayer.FAJR,t.next.prayer);assertEquals(2027,t.next.time.atZone(p.city.zoneId).year)}
    @Test fun exactBoundaryAdvancesAndResetsRing() {val now=Instant.parse("2026-11-06T12:00:00Z");val events=calculator.around(now,Preferences()).flatMap {it.events};val prayer=events.first {it.prayer==Prayer.ASR};val t=timeline(events,prayer.time)!!;assertEquals(Prayer.MAGHRIB,t.next.prayer);assertEquals(0.0,t.progress,0.00001)}
    @Test fun countdownUsesTimestampAfterResume() {val t=Timeline(PrayerEvent(Prayer.ASR,Instant.EPOCH),PrayerEvent(Prayer.MAGHRIB,Instant.ofEpochSecond(3600)),Instant.ofEpochSecond(1800));assertEquals(1800,t.remainingSeconds);assertEquals(0.5,t.progress,0.00001);assertEquals("00:30:00",countdown(t.remainingSeconds))}
    @Test fun dstSpringAndAutumnUseZoneRules() {val ny=Cities.all.first {it.zone=="America/New_York"};for(pair in listOf(LocalDate.of(2026,3,7) to LocalDate.of(2026,3,8),LocalDate.of(2026,10,31) to LocalDate.of(2026,11,1))) {val a=calculator.calculate(pair.first,Preferences(city=ny,method=Method.MWL));val b=calculator.calculate(pair.second,Preferences(city=ny,method=Method.MWL));assertTrue(a.complete && b.complete);val x=a.events[2].time.atZone(ny.zoneId);val y=b.events[2].time.atZone(ny.zoneId);assertNotEquals(x.offset,y.offset);assertTrue(kotlin.math.abs(Duration.between(x.toLocalTime(),y.toLocalTime()).toMinutes()) in 55..65)}}
    @Test fun worldCitiesHaveLocalDateAtSolarNoon() {for(city in Cities.all) {val date=LocalDate.of(2026,4,15);val day=calculator.calculate(date,Preferences(city=city,method=Method.MWL));assertTrue(city.name,day.complete);assertEquals(date,day.events.first {it.prayer==Prayer.DHUHR}.time.atZone(city.zoneId).toLocalDate())}}
    @Test fun highLatitudeRulesBoundTwilightAndPolarDayIsExplicit() {val london=Cities.all.first {it.zone=="Europe/London"};for(rule in HighLatitude.entries) assertTrue(calculator.calculate(LocalDate.of(2026,6,21),Preferences(city=london,method=Method.MWL,highLatitude=rule)).complete);val polar=calculator.calculate(LocalDate.of(2026,6,21),Preferences(city=City("Tromso",69.6492,18.9553,"Europe/Oslo")));assertFalse(polar.complete);assertNotNull(polar.warning)}
    @Test fun ramadanIshaIntervalChangesByHijriCalendar() {val ramadan=LocalDate.from(HijrahDate.of(1447,9,1));for(date in listOf(ramadan.minusDays(1),ramadan,ramadan.plusDays(40))) {val d=calculator.calculate(date,Preferences());val minutes=Duration.between(d.events.first {it.prayer==Prayer.MAGHRIB}.time,d.events.first {it.prayer==Prayer.ISHA}.time).toMinutes();assertEquals(if(HijrahDate.from(date).get(ChronoField.MONTH_OF_YEAR)==9)120L else 90L,minutes)}}
    @Test fun arabicMarkersAndMidnightNoon() {val p=Preferences(city=City("UTC",0.0,0.0,"UTC"));assertEquals("12:00 ص",displayTime(Instant.parse("2026-01-01T00:00:00Z"),p));assertEquals("12:00 م",displayTime(Instant.parse("2026-01-01T12:00:00Z"),p));assertEquals("13:05",displayTime(Instant.parse("2026-01-01T13:05:00Z"),p.copy(hour24=true)))}
    @Test fun invalidCoordinatesAndDurationsRejected() {assertThrows(IllegalArgumentException::class.java) {City("x",Double.NaN,0.0,"UTC")};assertThrows(IllegalArgumentException::class.java) {Preferences(durationMinutes=121)};assertThrows(IllegalArgumentException::class.java) {Preferences(enabled=setOf(Prayer.SUNRISE))}}
}
